#include <stdio.h>
#include <stdlib.h>
/* line is a complete string without its newline delimiter. */
int parse_grade(const char *line, int line_number, int *grade) {
    char *end;
    errno = 0;
    long value = strtol(line, &end, 10);
    while (isspace((unsigned char)*end)) ++end;
    if (end == line || *end != '\0' || errno == ERANGE || value < 0 || value > 100) {
        fprintf(stderr, "Error at line %d: invalid input %s\n", line_number, line);
        return 0;
    }
    *grade = (int)value;
    return 1;
}

